"""Generate `device.vectors`, the golden vectors of the device protocol.

The bytes are built by hand from literal JSON text and `struct` packing, never by a codec
under test. The file format is described in README.md. Run from the repo root:

    uv run python docs/protocol/vectors/generate.py
"""

from __future__ import annotations

import struct
import textwrap
from dataclasses import dataclass
from pathlib import Path

