HEADER = """\
# tinyaisense device-protocol golden vectors, format 1.
# Generated by generate.py: edit that, not this file. The format is in README.md."""


@dataclass(frozen=True)
class Part:
    """A run of bytes, with comment lines that say what they are."""

    data: bytes
    notes: tuple[str, ...] = ()


@dataclass(frozen=True)
class Vector:
    name: str
    layer: str
    expect: str
    parts: tuple[Part, ...]
    canon: tuple[Part, ...] | None = None
    params: tuple[tuple[str, int], ...] = ()


def frame(
    body: bytes, *, ftype: int = 1, flags: int = 0, length: int | None = None, note: str = ""
) -> Part:
    """A TCP frame: `type u8, flags u8, len u16 LE`, then the body."""
    n = len(body) if length is None else length
    notes = (f"frame type={ftype} flags={flags} len={n}", *((note,) if note else ()))
    return Part(struct.pack("<BBH", ftype, flags, n) + body, notes)


def js(text: str, **kwargs: int) -> Part:
    """A JSON frame holding `text` verbatim."""
    return frame(text.encode(), note=text, **kwargs)


def tcp(name: str, expect: str, *parts: Part, canon: tuple[Part, ...] | None = None) -> Vector:
    return Vector(f"tcp/{name}", "tcp", expect, parts, canon)


ECHO_FORMATS = '[{"codec":"pcm_s16le","rate":16000,"channels":1,"frame_ms":[10,20]}]'
