def manifest(omit: tuple[str, ...] = (), **fields: str) -> str:
    """The Atom Echo Manifest as JSON text, with some fields replaced or left out."""
    base = {
        "protocol": "1",
        "device_id": '"a1b2c3d4e5f6"',
        "board": '"m5stack-atom-echo"',
        "firmware": '"0.1.0-3-g1a2b3c4"',
        "capabilities": ECHO_CAPS,
        "exclusive": '[["mic","speaker"]]',
    }
    base.update(fields)
    return "{" + ",".join(f'"{k}":{v}' for k, v in base.items() if k not in omit) + "}"


def hello(manifest_text: str | None = None, token: str = "null", udp_port: str = "50123") -> str:
    m = manifest() if manifest_text is None else manifest_text
    return f'{{"type":"hello","token":{token},"udp_port":{udp_port},"manifest":{m}}}'


CONN_ID = 0xA1B2C3D4
BUTTON_DOWN = '{"type":"event","seq":7,"cap":"button","name":"down","ts":3600000123,"data":{}}'


def dgram(
    payload: bytes,
    *,
    kind: int = 1,
    stream: int = 3,
    flags: int = 0,
    seq: int = 0,
    ts: int = 0,
    conn_id: int = CONN_ID,
    note: str = "",
) -> Part:
    """A UDP datagram: the 20-byte LE header, then the payload."""
    header = struct.pack("<IBBHIQ", conn_id, kind, stream, flags, seq, ts)
    notes = (
        f"conn_id=0x{conn_id:08x} kind={kind} stream={stream} flags=0x{flags:04x}"
        f" seq={seq} ts={ts}",
        f"payload: {len(payload)} bytes" + (f", {note}" if note else ""),
    )
    return Part(header + payload, notes)


def pcm(size: int) -> bytes:
    """`size` bytes of arbitrary PCM."""
    return bytes((i * 37 + 11) % 256 for i in range(size))


def pcm_params(
    final: bool, rate: int = 16000, channels: int = 1, frame_ms: int = 10
) -> tuple[tuple[str, int], ...]:
    """Params: check the payload as a pcm_s16le frame of this format."""
    return (("rate", rate), ("channels", channels), ("frame_ms", frame_ms), ("final", int(final)))


def udp(
    name: str,
    expect: str,
    part: Part,
    *,
    canon: Part | None = None,
    params: tuple[tuple[str, int], ...] = (),
) -> Vector:
    return Vector(
        f"udp/{name}", "udp", expect, (part,), None if canon is None else (canon,), params
    )


