def _escape(char: str) -> str:
    code = ord(char)
    return (
        f"\\x{code:02x}"
        if code < 0x100
        else f"\\u{code:04x}"
        if code < 0x10000
        else f"\\U{code:08x}"
    )


def _notes(prefix: str, notes: tuple[str, ...]) -> list[str]:
    lines: list[str] = []
    for note in notes:
        ascii_note = "".join(c if " " <= c <= "~" else _escape(c) for c in note)
        lines += [f"{prefix}{chunk}" for chunk in textwrap.wrap(ascii_note, MAX_LINE - len(prefix))]
    return lines


def _hex(keyword: str, data: bytes) -> list[str]:
    return [
        f"{keyword} " + data[i : i + HEX_PER_LINE].hex(" ")
        for i in range(0, len(data), HEX_PER_LINE)
    ]


def _parts(keyword: str, parts: tuple[Part, ...]) -> list[str]:
    lines: list[str] = []
    for part in parts:
        lines += _notes("# ", part.notes)
        lines += _hex(keyword, part.data)
    return lines


def render(vectors: list[Vector]) -> str:
    names = [v.name for v in vectors]
    assert len(names) == len(set(names)), "duplicate vector names"
    lines = HEADER.splitlines()
    for v in vectors:
        lines += ["", f"vector {v.name}", f"layer {v.layer}"]
        lines += [f"param {key} {value}" for key, value in v.params]
        lines.append(f"expect {v.expect}")
        lines += _parts("hex", v.parts)
        if v.canon is not None:
            lines.append("# canonical re-encoding:")
            lines += _parts("canon", v.canon)
        lines.append("end")
    assert all(len(line) <= MAX_LINE and line.isascii() for line in lines)
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    OUT.write_text(render(VECTORS), encoding="ascii")
    print(f"wrote {len(VECTORS)} vectors to {OUT}")
